            for(int b = 0; b < births && free.size() > 0; b++) {
                Location loc = free.remove(0);
                Lion young = new Lion(false, field, loc);
                if (this.isInfected()) {
                    young.setInfected();
                }
                newLions.add(young);
            }
        }
        return null;
